mapper.select:
SELECT id, classroom_id, question_id, question_title, publish_order, is_required, start_time, end_time, create_time, update_time, is_deleted FROM mg_classroom_question WHERE is_deleted = 0
AND classroom_id = #{classroomId}
ORDER BY publish_order ASC, create_time ASC

SELECT cq.id, cq.classroom_id, cr.course_id, cr.course_name as classroom_name, cq.question_id, cq.question_title, cq.publish_order, cq.is_required, cq.start_time, cq.end_time FROM mg_classroom_question cq LEFT JOIN mg_course_record cr ON cq.classroom_id = cr.id AND cr.is_deleted = 0 WHERE cq.is_deleted = 0
AND cq.classroom_id = #{classroomId}
AND cr.course_id = #{courseId}
AND cq.question_title LIKE CONCAT('%', #{title}, '%')
AND cq.is_required = #{isRequired}
AND cq.start_time >= #{startTime}
AND cq.start_time <= #{endTime}
ORDER BY cq.publish_order ASC, cq.create_time ASC
